mapper.select:
SELECT 
FROM product_spu

    AND deleted = 0

        AND name LIKE CONCAT('%', #{keyword,jdbcType=VARCHAR}, '%')


        AND brand_id = #{brandId,jdbcType=BIGINT}


        AND category_id = #{categoryId,jdbcType=BIGINT}


        AND publish_status = #{publishStatus,jdbcType=TINYINT}


        AND verify_status = #{verifyStatus,jdbcType=TINYINT}


        AND new_status = #{newStatus,jdbcType=TINYINT}


        AND recommend_status = #{recommendStatus,jdbcType=TINYINT}


ORDER BY sort, id DESC

SELECT ps.* FROM product_spu ps WHERE ps.deleted = 0 AND ps.publish_status = 1
AND ps.name LIKE CONCAT('%', #{query.keyword}, '%')
AND ps.brand_id IN
#{brandId}
AND ps.category_id = #{query.categoryId}
AND ps.min_price >= #{query.minPrice}
AND ps.max_price <= #{query.maxPrice}
ORDER BY ps.sale DESC
ORDER BY ps.min_price ASC
ORDER BY ps.min_price DESC
ORDER BY ps.create_time DESC
ORDER BY ps.sort DESC, ps.id DESC

SELECT ps.id
FROM product_spu ps
WHERE ps.deleted = 0
  AND ps.id IN

      #{spuId}


    AND ps.name LIKE CONCAT('%', #{query.keyword}, '%')


    AND ps.brand_id = #{query.brandId}


    AND ps.category_id = #{query.categoryId}

ORDER BY ps.sort DESC, ps.id DESC

SELECT ps.brand_id as id, ps.brand_name as name, COUNT(*) as count
FROM product_spu ps
WHERE ps.deleted = 0 AND ps.publish_status = 1

    AND ps.name LIKE CONCAT('%', #{query.keyword}, '%')


    AND ps.category_id = #{query.categoryId}


    AND ps.min_price >= #{query.minPrice}


    AND ps.max_price <= #{query.maxPrice}


GROUP BY ps.brand_id, ps.brand_name
HAVING COUNT(*) > 0
ORDER BY count DESC

SELECT ps.category_id as id, ps.category_name as name, COUNT(*) as count FROM product_spu ps WHERE ps.deleted = 0 AND ps.publish_status = 1
AND ps.name LIKE CONCAT('%', #{query.keyword}, '%')
AND ps.brand_id IN
#{brandId}
AND ps.min_price >= #{query.minPrice}
AND ps.max_price <= #{query.maxPrice}
GROUP BY ps.category_id, ps.category_name HAVING COUNT(*) > 0 ORDER BY count DESC

SELECT pav.attr_id as attrId, pav.attr_name as attrName, pav.attr_value as `value`, COUNT(DISTINCT ps.id) as count FROM product_spu ps INNER JOIN product_attribute_value pav ON pav.spu_id = ps.id WHERE ps.deleted = 0 AND ps.publish_status = 1
AND ps.name LIKE CONCAT('%', #{query.keyword}, '%')
AND ps.brand_id IN
#{brandId}
AND ps.category_id = #{query.categoryId}
AND ps.min_price >= #{query.minPrice}
AND ps.max_price <= #{query.maxPrice}
GROUP BY pav.attr_id, pav.attr_name, pav.attr_value HAVING COUNT(DISTINCT ps.id) > 0 ORDER BY pav.attr_id, count DESC

SELECT MIN(ps.min_price) as min, MAX(ps.max_price) as max FROM product_spu ps WHERE ps.deleted = 0 AND ps.publish_status = 1
AND ps.name LIKE CONCAT('%', #{query.keyword}, '%')
AND ps.brand_id IN
#{brandId}
AND ps.category_id = #{query.categoryId}
